#include <stdio.h>
int main(void) {
    int value = 7;
    printf("%d\n", value);
    return 0;
}

int sum = 0;
for (int i = 1; i <= 3; ++i) {
    sum += i;
}

int samples[4] = {-2, 0, 5, 8};
int positive = 0;
for (int i = 0; i < 4; ++i) {
    if (samples[i] > 0) ++positive;
}

int value = 7;
int *p = &value;
*p = -3;
/* 此时 value 为 -3，p 仍指向 value。 */

enum Mode { STOPPED, RUNNING };
struct Device {
    enum Mode mode;
    int command;
};
struct Device car = {STOPPED, 0};

unsigned flags = 0;
flags |= (1u << 2);   /* 设置第 2 位 */
flags &= ~(1u << 2);  /* 清除第 2 位 */
